/** Every token with its value, as the application sends them. */
export interface Tokens {
  /** The window behind the panes. */
  readonly "color.surface": string;
  /** A pane's background around its terminal. */
  readonly "color.card": string;
  /** A pane's header. */
  readonly "color.card-header": string;
  /** Lines between and around things. */
  readonly "color.border": string;
  /** The border of the pane that has the focus. */
  readonly "color.border-focus": string;
  /** Text. */
  readonly "color.text": string;
  /** Text that matters less. */
  readonly "color.text-muted": string;
  /** Text on a strong colour. */
  readonly "color.text-inverse": string;
  /** What is selected or active. */
  readonly "color.accent": string;
  /** Text on the accent colour. */
  readonly "color.accent-text": string;
  /** A button or field at rest. */
  readonly "color.control": string;
  /** A button or field under the pointer. */
  readonly "color.control-hover": string;
  /** A button or field being pressed. */
  readonly "color.control-active": string;
  /** Menus, the command palette and other things that float. */
  readonly "color.popover": string;
  /** What dims the window behind a dialog. */
  readonly "color.overlay": string;
  /** Where something being dragged would land. */
  readonly "color.drop-preview": string;
  /** Something worth knowing. */
  readonly "color.status.info": string;
  /** Something that went well. */
  readonly "color.status.success": string;
  /** Something to look at. */
  readonly "color.status.warning": string;
  /** Something that went wrong. */
  readonly "color.status.danger": string;
  /** Terminal text. */
  readonly "terminal.fg": string;
  /** The terminal's background. */
  readonly "terminal.bg": string;
  /** The cursor. */
  readonly "terminal.cursor": string;
  /** The character under a block cursor. */
  readonly "terminal.cursor-text": string;
  /** The background of selected text. */
  readonly "terminal.selection": string;
  /** Selected text. */
  readonly "terminal.selection-text": string;
  /** The background of text a search found. */
  readonly "terminal.search-match": string;
  /** The background of the match a search is at. */
  readonly "terminal.search-active": string;
  /** ANSI black. */
  readonly "terminal.palette.0": string;
  /** ANSI red. */
  readonly "terminal.palette.1": string;
  /** ANSI green. */
  readonly "terminal.palette.2": string;
  /** ANSI yellow. */
  readonly "terminal.palette.3": string;
  /** ANSI blue. */
  readonly "terminal.palette.4": string;
  /** ANSI magenta. */
  readonly "terminal.palette.5": string;
  /** ANSI cyan. */
  readonly "terminal.palette.6": string;
  /** ANSI white. */
  readonly "terminal.palette.7": string;
  /** ANSI bright black. */
  readonly "terminal.palette.8": string;
  /** ANSI bright red. */
  readonly "terminal.palette.9": string;
  /** ANSI bright green. */
  readonly "terminal.palette.10": string;
  /** ANSI bright yellow. */
  readonly "terminal.palette.11": string;
  /** ANSI bright blue. */
  readonly "terminal.palette.12": string;
  /** ANSI bright magenta. */
  readonly "terminal.palette.13": string;
  /** ANSI bright cyan. */
  readonly "terminal.palette.14": string;
  /** ANSI bright white. */
  readonly "terminal.palette.15": string;
  /** The font of terminals. */
  readonly "font.family": string;
  /** The fonts tried after it. */
  readonly "font.fallback": readonly string[];
  /** The size of terminal text. */
  readonly "font.size": number;
  /** The height of a line, as a multiple of the size. */
  readonly "font.line-height": number;
  /** The weight of ordinary terminal text. */
  readonly "font.weight": number;
  /** The weight of bold terminal text. */
  readonly "font.bold-weight": number;
  /** The font of everything but terminals. */
  readonly "font.ui-family": string;
  /** The size of that text. */
  readonly "font.ui-size": number;
  /** The space between panes and around them. */
  readonly "space.gap": number;
  /** The space between a pane's edge and its text. */
  readonly "space.padding": number;
  /** The radius of a pane's corners. */
  readonly "radius.card": number;
  /** The radius of a button's or field's corners. */
  readonly "radius.control": number;
  /** The height of a pane's header. */
  readonly "size.header": number;
  /** The height of the bar at the top of a window. */
  readonly "size.topbar": number;
  /** The height of a tab. */
  readonly "size.tab": number;
  /** The width of a border. */
  readonly "size.border": number;
  /** The width of the ring around what has the focus. */
  readonly "size.focus-ring": number;
  /** How much a pane without the focus is dimmed. */
  readonly "opacity.dim": number;
  /** How opaque something that cannot be used is. */
  readonly "opacity.disabled": number;
  /** How opaque the picture behind the panes is. */
  readonly "opacity.background-image": number;
  /** The shadow of a pane. */
  readonly "shadow.card": string;
  /** The shadow of the pane that has the focus. */
  readonly "shadow.card-focus": string;
  /** The shadow of a floating pane. */
  readonly "shadow.floating": string;
  /** The shadow of a menu or dialog. */
  readonly "shadow.popover": string;
  /** A picture behind the panes. */
  readonly "background.image": string | null;
  /** How much that picture is blurred. */
  readonly "background.blur": number;
}

